class Client
{
    public const MSG_OOB = 1;
    public const MSG_PEEK = 2;
    public const MSG_DONTWAIT = 64;
    public const MSG_WAITALL = 256;
    public const SHUT_RDWR = 2;
    public const SHUT_RD = 0;
    public const SHUT_WR = 1;
    public $errCode = 0;
    public $sock = -1;
    public $reuse = false;
    public $reuseCount = 0;
    public $type = 0;
    public $id;
    public $setting;

/**
 * <div id="swoole-client.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">Swoole\Client::__construct</h1>  <p class="verinfo">(PECL swoole &gt;= 1.9.0)</p><p class="refpurpose"><span class="refname">Swoole\Client::__construct</span> — <span class="dc-title">Create Swoole sync or async TCP/UDP client, with or without SSL.</span></p> </div> <div class="refsect1 description" id="refsect1-swoole-client.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Swoole\Client::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$sock_type</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$is_async</span><span class="initializer"> = ?</span></span>)</div>  <p class="para rdfs-comment">  </p> </div> <div class="refsect1 parameters" id="refsect1-swoole-client.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">sock_type</span></dt>    <dd>     <p class="para">      The type of socket: SWOOLE_TCP, SWOOLE_UDP, SWOOLE_ASYNC, SWOOLE_SSL, SWOOLE_KEEP.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">is_async</span></dt>    <dd>     <p class="para">      Synchronous or asynchronous client.     </p>    </dd>     </dl> </div></div>
 */
    public function __construct($type, $async = null, $id = null) {}

/**
 * <div id="swoole-client.destruct" class="refentry"> <div class="refnamediv">  <h1 class="refname">Swoole\Client::__destruct</h1>  <p class="verinfo">(PECL swoole &gt;= 1.9.0)</p><p class="refpurpose"><span class="refname">Swoole\Client::__destruct</span> — <span class="dc-title">Destruct the Swoole client.</span></p> </div> <div class="refsect1 description" id="refsect1-swoole-client.destruct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Swoole\Client::__destruct</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">  </p>  <div class="warning"><strong class="warning">警告</strong><p class="simpara">本函数还未编写文档，仅有参数列表。</p></div> </div> <div class="refsect1 parameters" id="refsect1-swoole-client.destruct-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div></div>
 */
